INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, fees, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('Newton Community Education Summer Camp', 'Newton Community Education (Newton Public Schools)', 'https://newtoncommunityed.org/summercamp/', 'https://newtoncommunityed.org/summercamp/', 'nce-staff@newton.k12.ma.us', '617-559-6999', '457 Walnut Street', 'Newton', 'MA', '02460', 'Boston, MA', 'day', ARRAY['STEM','arts','sports','performing_arts']::text[], NULL, ARRAY['3D printing','Minecraft and coding','Circuits and engineering','Filmmaking','Arts and crafts','Zentangle drawing','Chess','Dungeons & Dragons','Tennis','Soccer','Volleyball','Cheer','Gym games','Musical theater (5-week Willy Wonka Jr.)','Counselor-in-Training']::text[], NULL, NULL, NULL, 0, 12, 'Summer camps run by Newton Community Education, part of Newton Public Schools, at Newton North High School and Horace Mann Elementary School. Families pick weekly half-day (9 AM to 12 PM) or full-day (to 3:30 PM) camps for kids entering kindergarten through high school, from 3D printing and filmmaking to tennis and chess, plus a 5-week theater camp and a CIT program.', NULL, NULL, 280, 650, NULL, 'week', TRUE, NULL, NULL, TRUE, 'A $10 non-refundable registration fee per session. Withdraw from a summer camp by June 1 for a refund minus a $50 cancellation fee per camp per student; no refunds after June 1. Transfers to another NCE summer class may be possible for a fee.', NULL, NULL, NULL, NULL, 2027, '[{"name": "Registration fee", "amount": 10, "per": "session", "required": true, "note": "Non-refundable, due once per session"}, {"name": "Extended day", "amount": 75, "per": "week", "required": false, "note": "4 to 5 pm, grades K to 5. The four day week of July 6 is $60.", "source_url": "https://newtoncommunityed.org/summercamp/"}]'::jsonb, '744f8ea4-93d4-57fc-be6e-2c6fbdb7bdfb', 'newton-community-education-newton', ST_GeogFromText('SRID=4326;POINT(-71.2092 42.337)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://newtoncommunityed.org','https://newtoncommunityed.org/about-us/policies/','https://newtoncommunityed.org/summercamp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Music @ Tufts', 'Tufts University Department of Music', 'https://as.tufts.edu/music/community-programs/summer-music', 'https://docs.google.com/forms/d/e/1FAIpQLSccOCXPVmz-zqxf6XhR7XvvYR7kVXQdWpKn8jn6hvY7U7kROA/viewform', 'summermusic@tufts.edu', '617-627-3564', '20 Talbot Avenue', 'Medford', 'MA', '02155', 'Boston, MA', 'specialty', ARRAY['performing_arts']::text[], ARRAY['arts']::text[], ARRAY['singing','african drumming','piano','violin','guitar','ukulele','music and movement','outdoor games']::text[], NULL, 7, 12, NULL, NULL, 'Two week music day program for ages 7 to 12 in Tufts University''s Granoff Music Center in Medford. Children take small group instrument classes, singing, drumming and music and movement, eat lunch in the dining hall and finish with a family concert.', 'both', NULL, 1200, 1200, NULL, 'session', TRUE, NULL, TRUE, TRUE, 'A $150 deposit is due at registration and is not refundable. The $1,050 balance is due by June 15, 2027; registrations after that date pay a $50 late fee if space remains.', NULL, NULL, NULL, NULL, 2027, '[{"name": "Aftercare", "amount": 15, "per": "hour", "required": false, "note": "Until 5:30 pm, per child"}]'::jsonb, 'b7586d7b-6c24-5369-ba0d-4eb7d0cbf0a3', 'summer-music-at-tufts-medford', ST_GeogFromText('SRID=4326;POINT(-71.1062 42.4184)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://as.tufts.edu/music/community-programs/summer-music']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Chinqueka', 'Ebner Camps Inc.', 'https://chinqueka.com/', 'https://chinqueka.campintouch.com/ui/forms/application/camper/App', NULL, '860-567-9678', '1519 Bantam Road', 'Bantam', 'CT', '06750', 'Connecticut', 'sleepaway', ARRAY['sports','arts','adventure']::text[], NULL, ARRAY['Horseback riding (extra fee)','Climbing and zip line','High ropes','Archery','Go-karts','Waterskiing','Sailing','Canoeing','Kayaking and rowing','Paddleboarding','Swimming','Synchronized swimming','Soccer','Field hockey','Tennis','Gymnastics','Cheerleading','Dance','Drama','Music','Ceramics','Arts and crafts','Jewelry making','Photography','Culinary arts','STEM','Overnight camping']::text[], 'girls', 7, 16, NULL, NULL, 'Camp Chinqueka is an overnight summer camp for girls ages 7 to 16 in Bantam, Connecticut, with sessions from one week (Rookie) to a full eight-week season between June 27 and August 21, 2027. Activities range from waterskiing, sailing and climbing to dance, ceramics and horseback riding. Tuition includes meals, snacks, laundry, towel service, gratuities, the canteen shop and all on-camp activities.', NULL, NULL, 2675, 13230, NULL, NULL, NULL, TRUE, TRUE, NULL, 'Half of the deposit cannot be refunded under any circumstances, and the whole deposit becomes non-refundable after 12/31/26. Balances are due May 1. Unused canteen money is not refunded.', NULL, 'Campers get swim instruction from American Red Cross certified counselors, from Level 1 to Lifeguard Training, plus free swim in the camp''s lake. Waterskiing, shared with Camp Awosting, is on Bantam Lake, 7 miles away.', NULL, NULL, 2027, '[{"name": "Canteen", "amount": 80, "per": "session", "required": true, "note": "Spending money for camp clothing, merch and out of camp trips, not refunded if unused. $80 for 1 week, $125 for 2, $150 for 3, $175 for 4, $200 for 6, $250 for 8"}, {"name": "Airport transportation", "amount": 250, "per": "once", "required": false, "note": "Each way"}, {"name": "International camper package", "amount": 600, "per": "session", "required": false, "note": "Linen and trunk rental, JFK airport pick up and drop off, toiletries"}, {"name": "Linen and trunk rental", "amount": 200, "per": "session", "required": false, "note": "1 to 4 weeks; $250 for 5 to 8 weeks"}, {"name": "Birthday party", "amount": 100, "per": "once", "required": false}, {"name": "Senior trip", "amount": 650, "per": "once", "required": false, "note": "During Sessions 2 and 4"}, {"name": "Changeover day trip", "amount": 100, "per": "once", "required": false}, {"name": "Visiting day trip", "amount": 50, "per": "once", "required": false}, {"name": "Horseback riding", "amount": 80, "per": "hour", "required": false, "note": "Not paid from canteen money"}]'::jsonb, '77ccd8ad-838d-5024-93a3-36c43379ece4', 'camp-chinqueka-bantam', ST_GeogFromText('SRID=4326;POINT(-73.2423 41.7247)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://chinqueka.com/','https://chinqueka.com/activities/','https://chinqueka.com/dates-rates/','https://chinqueka.com/future-families/faqs/']::text[], '2026-11-13', '2026-11-13', TRUE),
('YMCA Camp of Maine', 'YMCA Camp Of Maine', 'https://www.maineycamp.org/', 'https://maineycamp.campintouch.com/ui/forms/application/camper/App', 'info@maineycamp.org', '207-395-4200', '305 Winthrop Center Rd', 'Winthrop', 'ME', '04364', 'Maine', 'sleepaway', ARRAY['sports','arts','outdoor','nature']::text[], NULL, ARRAY['Canoeing','Kayaking','Sailing','Paddle boarding','Snorkeling','Swim lessons','Free swim','Volleyball','Basketball','Tennis','Soccer','Yoga','Archery','Axe throwing','Challenge course','Overnight camping','Fishing','Outdoor cooking','Musical theater','Dance','Painting and drawing','Guitar and ukulele','Pottery/ceramics']::text[], 'coed', NULL, NULL, NULL, NULL, 'Overnight YMCA camp founded in 1915 on the shores of Lake Cobbossee in Winthrop, Maine, offering one- and two-week sessions for boys and girls. Programs listed include Traditional Camp, Explorer''s Camp and a LIT/CIT program.', NULL, NULL, 534, 2642, NULL, 'session', NULL, NULL, TRUE, TRUE, 'Balances are due June 1. The deposit ($125 a week, $250 a two-week session, per camper) is never refunded. Cancel more than 30 days before your session and you get 25% of the full tuition back; within 30 days there is no refund.', NULL, 'The camp is on Lake Cobbossee. Certified lifeguards run the waterfront, which offers canoeing, kayaking, sailing, paddle boarding, snorkeling, water games and free swim. Younger cabins (Kennebec Porch and Cobbossee) are all assigned a period of swim lessons.', NULL, NULL, 2027, '[{"name": "Traveler package", "amount": 470, "per": "session", "required": false, "note": "For campers flying in: laundry, bedding, airport transport and travel extras"}, {"name": "Airport transfer (Boston Logan)", "amount": 145, "per": "once", "required": false, "note": "Each way"}, {"name": "Airport transfer (Portland Jetport)", "amount": 85, "per": "once", "required": false, "note": "Each way"}, {"name": "Stay over between sessions", "amount": 150, "per": "once", "required": false, "note": "Per camper, for the weekend between two sessions", "source_url": "https://www.maineycamp.org/programs/dates-fees"}]'::jsonb, 'c5840250-9009-591a-9817-c0d6183987fb', 'ymca-camp-of-maine-winthrop', ST_GeogFromText('SRID=4326;POINT(-69.9631 44.31)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.maineycamp.org/','https://www.maineycamp.org/camp-life/activities','https://www.maineycamp.org/programs/dates-fees','https://www.maineycamp.org/programs/dates-fees/transfers-laundry']::text[], '2026-11-27', '2026-11-27', TRUE),
('YMCA Camp Boroughs', 'YMCA of Central Massachusetts (Boroughs Family Branch YMCA)', 'https://www.ymcaofcm.org/camp-boroughs/', 'https://operations.daxko.com/Online/5104/ProgramsV2/Search.mvc?keywords=&program_id=&expanded=categories%2Clocations&coming_soon=False&category_ids=CAT499&all_categories=false&location_ids=B371&all_locations=false&date_ranges%5B0%5D.start=&date_ranges%5B0%5D.end=&birth_dates=', 'lharding@ymcaofcm.org', NULL, '4 Valente Drive', 'Westborough', 'MA', '01581', 'Central & Western Massachusetts', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','outdoor','leadership']::text[], ARRAY['swimming','sports','arts and crafts','team games','archery','stem','water games','nature adventure zone','field trips']::text[], NULL, 3, 14, NULL, NULL, 'Outdoor YMCA day camp in Westborough for ages 3 to 12, with leadership and counselor in training programs for older kids. Campers swim, play sports, do crafts, STEM and archery (age 7 and up), and children 7 to 12 can add optional weekly field trips.', 'outdoor', NULL, 390, 460, NULL, 'week', NULL, NULL, FALSE, TRUE, 'The $50 weekly deposit is non refundable; other payments are refunded with two weeks'' notice. No refunds for behavior suspensions, illness, weather closures or days a family keeps the child home.', NULL, NULL, NULL, NULL, 2026, '[{"name": "Field trip", "amount": 50, "per": "day", "required": false, "note": "Optional weekly trips for ages 7 to 12, priced per trip: New England Aquarium, Connecticut Sun, Southwick''s Zoo, Basketball Hall of Fame, Patriots Training Camp."}, {"name": "Field trip (premium)", "amount": 75, "per": "day", "required": false, "note": "Optional trips for ages 7 to 12, priced per trip: Outdoor Escape Room, Six Flags (two dates), Boston Duck Boat Tours."}, {"name": "Birthday package", "amount": 60, "per": "once", "required": false, "note": "Optional; pizza lunch for the camper''s group and a camp celebration", "source_url": "https://www.ymcaofcm.org/wp-content/uploads/2026/01/2026-YMCA-Camp-Boroughs-Parent-Handbook.pdf?x27910"}]'::jsonb, '7c349652-fc14-527a-9c96-4aad83370969', 'ymca-camp-boroughs-westborough', ST_GeogFromText('SRID=4326;POINT(-71.6162 42.2695)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.ymcaofcm.org/camp-boroughs/','https://www.ymcaofcm.org/wp-content/uploads/2026/01/2026-YMCA-Camp-Boroughs-Parent-Handbook.pdf?x27910']::text[], '2026-11-25', '2026-11-25', TRUE),
('Wildwood Camp', 'Mass Audubon', 'https://www.massaudubon.org/programs-events/nature-camps/wildwood-camp/programs', 'https://www.massaudubon.org/programs?prg%5Bpid%5D%5B%5D=17542&prg%5Bdaterange%5D=&prg%5Bquery%5D=&prg%5Bprogram_types%5D%5B%5D=849&prg%5Binclude_camps%5D=1&prg%5Bsubmit%5D=&prg%5Bage_min%5D=&prg%5Bage_max%5D=', NULL, '603-899-5589', '27 Vining Road', 'Rindge', 'NH', '03461', 'New Hampshire', 'sleepaway', ARRAY['nature']::text[], NULL, ARRAY['Swimming and paddling on Hubbard Pond','Campfires and s''mores','Overnight camping trips','Tent setup and knot tying','High and low ropes courses','Archery','Hiking','Climbing','Kayaking','Backpacking','Themed camp days','Leadership training']::text[], NULL, 9, 17, NULL, NULL, 'Mass Audubon''s overnight nature camp on Hubbard Pond in Rindge, NH, for ages 9-17. Campers 9-14 come for one- or two-week sessions; teens choose weekly adventure trips, Counselors-in-Training or Environmental Leadership Teens. All sessions require a Mass Audubon Family membership.', NULL, NULL, 625, 3415, 1860, 'week', NULL, NULL, NULL, TRUE, NULL, NULL, 'The camp''s waterfront is on Hubbard Pond, where campers swim and paddle. The pages don''t describe swim tests or waterfront staffing.', NULL, NULL, 2027, '[{"name": "Membership", "amount": 85, "per": "year", "required": true, "note": "Mass Audubon Family membership or higher is required for every Wildwood session. Family is the lowest level that can register for camp."}, {"name": "Intersession", "amount": 215, "per": "once", "required": false, "note": "Per intersession, for overnight campers staying between consecutive sessions; includes laundry", "source_url": "https://www.massaudubon.org/programs-events/nature-camps/wildwood-camp/rates-dates"}]'::jsonb, 'ad9906ec-e17d-53f1-8d7a-e127616f9b1b', 'wildwood-camp-rindge', ST_GeogFromText('SRID=4326;POINT(-72.0132 42.7567)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.massaudubon.org/programs-events/nature-camps/wildwood-camp','https://www.massaudubon.org/programs-events/nature-camps/wildwood-camp/programs','https://www.massaudubon.org/programs-events/nature-camps/wildwood-camp/rates-dates','https://www.massaudubon.org/take-action/membership']::text[], '2026-11-27', '2026-11-27', TRUE),
('Camp Kettleford', 'Girl Scouts of the Green and White Mountains', 'https://www.girlscoutsgwm.org/en/activities/camp-and-outdoors/kettleford.html', NULL, NULL, NULL, '26 Camp Rd', 'Bedford', 'NH', '03110', 'New Hampshire', 'day', ARRAY['general','nature']::text[], ARRAY['arts','outdoor','leadership','swimming']::text[], ARRAY['crafts','target sports','paddling','swimming','campfire cooking','sing-alongs','nature hikes','low challenge course','theme weeks','badge work']::text[], 'girls', 5, 16, 0, 10, 'Girl Scout day camp on 30 wooded acres by Sandy and Sebbins Ponds in Bedford for girls entering kindergarten through grade 10, with weekly themed programs by grade. Campers do crafts, target sports, paddling, swimming, campfire cooking and hikes; drop off 8:30 to 8:45, pick up 4:00 to 5:00, buses for most weeks.', 'outdoor', NULL, NULL, NULL, 375, 'week', NULL, TRUE, NULL, TRUE, 'A $100 deposit, included in the session price, is not refundable.', NULL, NULL, NULL, NULL, 2027, '[{"name": "Membership", "amount": 80, "per": "year", "required": true, "note": "Girl Scout dues for girl members, membership year October 1, 2026 to September 30, 2027. Campers who are not Girl Scouts must buy it to enroll; current members already have it."}, {"name": "Bus", "amount": 35, "per": "session", "required": false, "note": "Stops and times posted by April 2027", "source_url": "https://www.girlscoutsgwm.org/en/activities/camp-and-outdoors/camp-transportation.html"}]'::jsonb, 'f756f91d-63b7-5864-8d23-d435b31493f8', 'camp-kettleford-bedford', ST_GeogFromText('SRID=4326;POINT(-71.5369 42.9356)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.girlscoutsgwm.org/en/activities/camp-and-outdoors/camp-transportation.html','https://www.girlscoutsgwm.org/en/activities/camp-and-outdoors/kettleford.html','https://www.girlscoutsgwm.org/en/get-involved/join.html']::text[], '2026-11-27', '2026-11-27', TRUE),
('Summer at Far Brook', 'Far Brook School', 'https://www.farbrook.org/summer-at-far-brook', 'https://summeratfarbrook.campbrainregistration.com/', 'summer@farbrook.org', '973-379-3442', '52 Great Hills Road', 'Short Hills', 'NJ', '07078', 'Northern New Jersey', 'day', ARRAY['general','arts']::text[], ARRAY['STEM','sports','performing_arts','outdoor']::text[], ARRAY['creative arts','science','music','theater','archery','outdoor play','water play','sports clinics','swim lessons']::text[], NULL, 3, NULL, NULL, NULL, 'Summer day camp on the Far Brook School campus in Short Hills, open to all families. Day campers rotate through art, science, music, theater, archery and outdoor play around a weekly theme, with water play on Fridays; the school also runs week long STEAM and specialty classes, sport clinics and leadership programs for older campers.', 'both', NULL, 495, 715, 695, 'week', TRUE, NULL, FALSE, NULL, '$50 registration fee is not refundable. Cancellations by May 31, 2026 are refunded less that fee; from June 1 families get a credit for unused weeks, good through summer 2027.', NULL, NULL, NULL, NULL, 2026, '[{"name": "Registration fee", "amount": 50, "per": "once", "required": true, "note": "Per camper, nonrefundable."}, {"name": "Swim lessons", "amount": 125, "per": "week", "required": false, "note": "Add-on to Day Camp full day for Nursery 4s and up, from June 16. The page prints \"add +$125\" on the weekly price line."}, {"name": "Extended care (morning)", "amount": 20, "per": "hour", "required": false, "note": "Extended Day AM, 8:00 to 9:00 am."}, {"name": "Extended care (afternoon)", "amount": 30, "per": "hour", "required": false, "note": "Extended Day PM, 3:30 to 5:30 pm."}]'::jsonb, 'c3a3834f-6722-54ac-8314-a1f70434620b', 'summer-at-far-brook-short-hills', ST_GeogFromText('SRID=4326;POINT(-74.3262 40.7412)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.farbrook.org/summer-at-far-brook','https://www.farbrook.org/summer-at-far-brook/day-camp']::text[], '2026-11-26', '2026-11-26', TRUE),
('ESF Summer Camps at Devon Preparatory School', 'ESF Camps', 'https://www.esfcamps.com/devon/', NULL, NULL, '610-688-3298', '363 N Valley Forge Rd', 'Devon', 'PA', '19333', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['sports','STEM','swimming','arts']::text[], ARRAY['swimming','swim lessons','sports','arts','science','engineering','technology','special events']::text[], NULL, NULL, 16, NULL, 10, 'ESF day camp on the Devon Preparatory School campus in Devon for boys and girls from rising preschool to grade 10. Campers are grouped by grade, swim with Red Cross certified lifeguards and instructors, and pick from more than 60 activities across sports, arts, science, engineering and technology.', 'both', NULL, 1530, 6615, NULL, 'session', TRUE, NULL, FALSE, NULL, 'Cancel by March 15, 2027 for a refund less the $50 registration fee (a full cancellation also costs $300 per child); from March 16 to June 1, 2027, a credit instead of a refund; no refunds or credits after June 1. An optional protection plan covers injury or illness.', NULL, NULL, NULL, NULL, 2027, '[{"name": "Lunch", "amount": 75, "per": "week", "required": false, "note": "Optional lunch program. Club OT extended day to 5:00 pm is included in tuition."}, {"name": "Extended care (5:00 to 5:30 pm)", "amount": 65, "per": "week", "required": false, "note": "Club OT extension past the 5:00 pm included in tuition; $55 for the four day holiday weeks. The page also shows an older 2025 table ($225, $70, $190); skipped.", "source_url": "https://www.esfcamps.com/devon/rates/extended-day/"}]'::jsonb, 'b636ed9f-eb14-582c-900a-e99d5bc45f31', 'esf-summer-camps-at-devon-prep-devon', ST_GeogFromText('SRID=4326;POINT(-75.4268 40.0489)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.esfcamps.com/about/policy-information/','https://www.esfcamps.com/devon/','https://www.esfcamps.com/devon/rates/','https://www.esfcamps.com/devon/rates/extended-day/']::text[], '2026-11-27', '2026-11-27', TRUE),
('ESF Summer Camps at Friends Select School', 'ESF Camps', 'https://www.esfcamps.com/friendsselect/', NULL, NULL, '215-298-9145', '17th Street & Benjamin Franklin Parkway', 'Philadelphia', 'PA', '19103', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['sports','STEM','swimming','arts']::text[], ARRAY['swimming','swim lessons','sports','arts','science','engineering','technology','special events']::text[], NULL, NULL, 15, NULL, 9, 'ESF day camp on the Friends Select School campus in Center City Philadelphia for boys and girls from rising preschool to grade 9. Campers are grouped by grade, swim with Red Cross certified lifeguards and instructors, and pick from more than 60 activities across sports, arts, science, engineering and technology.', 'both', NULL, 1390, 6650, NULL, 'session', TRUE, NULL, FALSE, NULL, 'Cancel by March 15, 2027 for a refund less the $50 registration fee (a full cancellation also costs $300 per child); from March 16 to June 1, 2027, a credit instead of a refund; no refunds or credits after June 1. An optional protection plan covers injury or illness.', NULL, NULL, NULL, NULL, 2027, '[{"name": "Extended care (morning and afternoon)", "amount": 235, "per": "week", "required": false, "note": "Club OT 7:30 am to 6:00 pm."}, {"name": "Extended care (morning)", "amount": 75, "per": "week", "required": false, "note": "Club OT drop off 7:30 to 8:45 am."}, {"name": "Extended care (afternoon)", "amount": 200, "per": "week", "required": false, "note": "Club OT pick up 3:30 to 6:00 pm."}, {"name": "Lunch", "amount": 60, "per": "week", "required": false, "note": "Optional lunch program. Campers with documented food allergies bring lunch from home.", "source_url": "https://www.esfcamps.com/friendsselect/rates/"}]'::jsonb, '0267f96a-2117-5f20-8432-08b8f1362d47', 'esf-summer-camps-at-friends-select-school-philadelphia', ST_GeogFromText('SRID=4326;POINT(-75.1652 39.9526)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.esfcamps.com/about/policy-information/','https://www.esfcamps.com/friendsselect/','https://www.esfcamps.com/friendsselect/rates-details/rates/','https://www.esfcamps.com/friendsselect/rates/','https://www.esfcamps.com/friendsselect/rates/extended-day/']::text[], '2026-11-27', '2026-11-27', TRUE),
('ESF Summer Camps at Montgomery School', 'ESF Camps', 'https://www.esfcamps.com/montgomery/', NULL, NULL, '610-827-1800', '1141 Kimberton Road', 'West Pikeland', 'PA', '19425', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['sports','STEM','swimming','arts']::text[], ARRAY['swimming','swim lessons','sports','arts','science','engineering','technology','special events']::text[], NULL, NULL, 16, NULL, 10, 'ESF day camp on the Montgomery School campus in Chester Springs for boys and girls from rising preschool to grade 10. Campers are grouped by grade, swim with Red Cross certified lifeguards and instructors, and pick from more than 60 activities across sports, arts, science, engineering and technology.', 'both', NULL, 1290, 5535, NULL, 'session', TRUE, NULL, FALSE, NULL, 'Cancel by March 15, 2027 for a refund less the $50 registration fee (a full cancellation also costs $300 per child); from March 16 to June 1, 2027, a credit instead of a refund; no refunds or credits after June 1. An optional protection plan covers injury or illness.', NULL, NULL, NULL, NULL, 2027, '[{"name": "Lunch", "amount": 60, "per": "week", "required": false, "note": "Optional lunch program. Club OT extended day to 5:00 pm is included in tuition."}, {"name": "Extended care (5:00 to 5:30 pm)", "amount": 65, "per": "week", "required": false, "note": "Club OT extension past the 5:00 pm included in tuition; $55 for the four day holiday weeks. The page also shows an older 2025 table ($225, $70, $190); skipped.", "source_url": "https://www.esfcamps.com/montgomery/rates/extended-day/"}]'::jsonb, '157484fa-3ecd-5eb8-b424-ab4c4e8806d9', 'esf-summer-camps-at-montgomery-school-chester-springs', ST_GeogFromText('SRID=4326;POINT(-75.6196 40.088)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.esfcamps.com/about/policy-information/','https://www.esfcamps.com/montgomery/','https://www.esfcamps.com/montgomery/rates/','https://www.esfcamps.com/montgomery/rates/extended-day/']::text[], '2026-11-27', '2026-11-27', TRUE),
('ESF Summer Camps at Norwood-Fontbonne Academy', 'ESF Camps', 'https://www.esfcamps.com/chestnuthill/', NULL, NULL, '215-247-7010', '8900 Norwood Avenue', 'Philadelphia', 'PA', '19118', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['sports','STEM','swimming','arts']::text[], ARRAY['swimming','swim lessons','sports','arts','science','engineering','technology','special events']::text[], NULL, NULL, 16, NULL, 10, 'ESF day camp on the Norwood-Fontbonne Academy campus in Chestnut Hill, Philadelphia for boys and girls from rising preschool to grade 10. Campers are grouped by grade, swim with Red Cross certified lifeguards and instructors, and pick from more than 60 activities across sports, arts, science, engineering and technology.', 'both', NULL, 1210, 5750, NULL, 'session', TRUE, NULL, FALSE, NULL, 'Cancel by March 15, 2027 for a refund less the $50 registration fee (a full cancellation also costs $300 per child); from March 16 to June 1, 2027, a credit instead of a refund; no refunds or credits after June 1. An optional protection plan covers injury or illness.', NULL, NULL, NULL, NULL, 2027, '[{"name": "Extended care (morning and afternoon)", "amount": 235, "per": "week", "required": false, "note": "Club OT 7:30 am to 6:00 pm."}, {"name": "Extended care (morning)", "amount": 75, "per": "week", "required": false, "note": "Club OT drop off 7:30 to 8:45 am."}, {"name": "Extended care (afternoon)", "amount": 200, "per": "week", "required": false, "note": "Club OT pick up 3:30 to 6:00 pm."}, {"name": "Lunch", "amount": 60, "per": "week", "required": false, "note": "Optional lunch program. Campers with documented food allergies bring lunch from home.", "source_url": "https://www.esfcamps.com/chestnuthill/rates/"}]'::jsonb, '76174041-c357-5e8c-80d7-1a0ee96f4512', 'esf-summer-camps-at-norwood-fontbonne-academy-philadelphia', ST_GeogFromText('SRID=4326;POINT(-75.1652 39.9526)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.esf