('ESF Summer Camps at The Haverford School', 'ESF Camps', 'https://www.esfcamps.com/haverford/', NULL, NULL, '610-642-0246', '450 Lancaster Avenue', 'Haverford', 'PA', '19041', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['sports','STEM','swimming','arts']::text[], ARRAY['swimming','swim lessons','sports','arts','science','engineering','technology','special events']::text[], NULL, NULL, 16, NULL, 10, 'ESF day camp on the The Haverford School campus in Haverford for boys and girls from rising preschool to grade 10. Campers are grouped by grade, swim with Red Cross certified lifeguards and instructors, and pick from more than 60 activities across sports, arts, science, engineering and technology.', 'both', NULL, 1580, 6080, NULL, 'session', TRUE, NULL, FALSE, NULL, 'Cancel by March 15, 2027 for a refund less the $50 registration fee (a full cancellation also costs $300 per child); from March 16 to June 1, 2027, a credit instead of a refund; no refunds or credits after June 1. An optional protection plan covers injury or illness.', NULL, NULL, NULL, NULL, 2027, '[{"name": "Extended care (morning and afternoon)", "amount": 235, "per": "week", "required": false, "note": "Club OT 7:30 am to 6:00 pm."}, {"name": "Extended care (morning)", "amount": 75, "per": "week", "required": false, "note": "Club OT drop off 7:30 to 8:45 am."}, {"name": "Extended care (afternoon)", "amount": 200, "per": "week", "required": false, "note": "Club OT pick up 3:30 to 6:00 pm."}, {"name": "Lunch", "amount": 70, "per": "week", "required": false, "note": "Optional lunch program. Campers with documented food allergies bring lunch from home.", "source_url": "https://www.esfcamps.com/haverford/rates/"}]'::jsonb, 'a38aaee3-69aa-539b-932a-783ed71254dd', 'esf-summer-camps-at-the-haverford-school-haverford', ST_GeogFromText('SRID=4326;POINT(-75.3101 40.0062)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.esfcamps.com/about/policy-information/','https: