('Miquon Day Camp', 'The Miquon School', 'https://www.miquon.org/camp/info-registration', 'https://miquondaycamp.campmanagement.com/p/request_for_info_m.php?action=enroll', 'campoffice@miquon.org', '610-828-1231', '2025 Harts Lane', 'Conshohocken', 'PA', '19428', 'Philadelphia, PA', 'day', ARRAY['general','nature']::text[], ARRAY['swimming','arts','performing_arts','sports']::text[], ARRAY['swimming','swim lessons','arts and crafts','athletics','drama','music','movement','nature','creek exploring','choice time']::text[], NULL, 5, 11, 0, 6, 'Traditional outdoor day camp on The Miquon School''s wooded campus in Whitemarsh Township for ages 5 to 11, with daily swimming including lessons, arts and crafts, athletics, drama, music, movement, nature and free choice time by the creek.', 'both', NULL, 525, 525, 525, 'week', TRUE, TRUE, NULL, NULL, 'Cancellations by email to the registrar. Early in the year Miquon keeps a 10% deposit and refunds the rest; from March 1 it keeps the deposit and half of other payments; from mid April there are no refunds, though week transfers may be possible for a fee.', NULL, '8 to 10 swim periods a week, four of them small group lessons, led by certified lifeguards.', TRUE, 'https://www.miquon.org/camp/info-registration', 2027, '[{"name": "Bus", "amount": 130, "per": "week", "required": false, "note": "For the first or only camper; $65 a week for each added sibling. No multi week discount."}, {"name": "Extended care (afternoon)", "amount": 125, "per": "week", "required": false, "note": "After Camp Care, end of the camp day to 6:00 pm; discounts for four weeks or more. Not for preschool or CIT campers.", "source_url": "https://www.miquon.org/camp/after-camp-care"}, {"name": "Extended care (afternoon, drop in)", "amount": 25, "per": "day", "required": false, "note": "After Camp Care by the day; call or email by noon.", "source_url": "https://www.miquon.org/camp/after-camp-care"}]'::jsonb, '59fe81fe-014e-5a4e-8d00-f290743b795d', 'miquon-day-camp-conshohocken', ST_GeogFromText('SRID=4326;POINT(-75.3041 40.0772)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.miquon.org/camp/a-campers-day-miquon','https://www.miquon.org/camp/a-campers-day-miquon/swimming','https://www.miquon.org/camp/after-camp-care','https://www.miquon.org/camp/camp-transportation','https://www.miquon.org/camp/contact-camp','https://www.miquon.org/camp/info-registration']::text[], '2026-11-26', '2026-11-26', TRUE),
('Wheeler Summer Camp', 'The Wheeler School', 'https://wheelersummercamp.com/', 'https://wssc.campintouch.com/ui/forms/application/camper/App', 'summercamp@wheelerschool.org', '508-336-8377', '357 Walker Street', 'Seekonk', 'MA', '02771', 'Providence, RI', 'day', ARRAY['general']::text[], ARRAY['swimming','outdoor','adventure','sports','arts']::text[], ARRAY['swim lessons','free swim','high ropes','field trips','specialty camps']::text[], 'coed', 3, 15, NULL, NULL, 'Traditional day camp on The Wheeler School''s 120-acre farm campus in Seekonk, with campers grouped by age, a daily swim lesson, ropes course and two-week specialty camps in athletics, arts and sciences. Buses run from Providence and nearby towns.', 'both', NULL, 1237, 1375, NULL, 'session', TRUE, TRUE, TRUE, TRUE, 'Non-refundable $150/session deposit. Full tuition refund through April 1, 2027; no refunds after that date. Balance due June 1, 2027; 3-installment payment plan available.', NULL, 'Daily swim lesson and free swim for all campers in a heated 25-meter outdoor pool.', TRUE, 'https://find.acacamps.org/program_profile.php?program_id=16422', 2027, '[{"name": "Extended care (afternoon)", "amount": 200, "per": "session", "required": false, "note": "PM Care 4:00 to 5:30 pm, per two week session, at the Seekonk campus."}, {"name": "Extended care and late bus", "amount": 250, "per": "session", "required": false, "note": "PM Care to 5:00 pm plus the late bus to Providence (arrives 5:30 pm), per two week session; includes the morning bus from Providence."}, {"name": "Bus", "amount": 150, "per": "session", "required": false, "note": "Per two week session, Summer 2027 routes from Providence, Attleboro and Pawtucket, East Bay and South County.", "source_url": "https://wheelersummercamp.com/familyinfo/transportation/"}, {"name": "Field trips", "amount": 100, "per": "session", "required": true, "note": "Upper Campers only, per two week session.", "source_url": "https://wheelersummercamp.com/familyinfo/tuition/"}]'::jsonb, 'a7f3e796-3acb-547b-97a7-701edb723524', 'wheeler-summer-camp-seekonk', ST_GeogFromText('SRID=4326;POINT(-71.337 41.8084)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://find.acacamps.org/program_profile.php?program_id=16422','https://wheelersummercamp.com/','https://wheelersummercamp.com/about/','https://wheelersummercamp.com/camps/traditional-camp/','https://wheelersummercamp.com/contact/','https://wheelersummercamp.com/familyinfo/extended-day-program/','https://wheelersummercamp.com/familyinfo/faqs/','https://wheelersummercamp.com/familyinfo/transportation/','https://wheelersummercamp.com/familyinfo/tuition/']::text[], '2026-10-02', '2026-10-02', TRUE),
('Brittany Harris Gymnastics Camps', 'Brown University Women''s Gymnastics coaching staff', 'https://www.brittanyharrisgymnasticscamps.com/', 'https://register.ryzer.com/camp.cfm?id=327444', 'brittanyharris.ent@gmail.com', NULL, 'Ocean State School of Gymnastics, 3 New England Way', 'Lincoln', 'RI', '02865', 'Providence, RI', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['Gymnastics']::text[], 'girls', 7, 18, NULL, NULL, 'Two-day commuter gymnastics camps for girls ages 7 to 18, from beginning levels to elite, hosted by the Brown University Women''s Gymnastics coaching staff with current Brown gymnasts, held at Ocean State School of Gymnastics in Lincoln, RI.', 'indoor', NULL, 323, 419, NULL, 'session', NULL, NULL, FALSE, NULL, 'No refund unless Registration Protection is bought at registration; $70 administrative fee on all cancellations; no cancellation refunds within 7 days of camp.', NULL, NULL, NULL, NULL, 2026, '[]'::jsonb, 'a66a17b8-b787-5b71-93ff-3ffb65fa9311', 'brittany-harris-gymnastics-camps-providence', ST_GeogFromText('SRID=4326;POINT(-71.4351 41.9212)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.brittanyharrisgymnasticscamps.com/','https://www.brittanyharrisgymnasticscamps.com/august-bears-gymnastics-summer.cfm','https://www.brittanyharrisgymnasticscamps.com/july-bears-gymnastics-summer.cfm']::text[], '2026-11-13', '2026-11-13', TRUE),
('United Sports Arena Recreational Summer Camp', 'United Sports Arena', 'https://www.unitedsportsarena.com/cricket-camps', 'https://www.unitedsportsarena.com/shop/summer-camp-2026-6549', 'contactus@unitedsportsarena.com', '(508) 709-5635', '839 Upper Union Street', 'Franklin', 'MA', '02038', 'Providence, RI', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['cricket','batting','bowling','fielding','box cricket','futsal','lego','puzzles','reading']::text[], 'coed', 5, NULL, NULL, NULL, 'An indoor cricket camp at United Sports Arena in Franklin for boys and girls 5 and up, all skill levels, grouped by age (5 to 9 and 10 plus). Days mix batting, bowling and fielding drills and box cricket games with free choice time for Lego, puzzles, futsal or reading.', 'indoor', NULL, 225, 399, 399, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '[{"name": "Extended care (before and after)", "amount": 15, "per": "hour", "required": false, "note": "Before and after camp; the page prints no hours for it."}]'::jsonb, '53918df9-4ec3-566b-895f-533faee93c67', 'united-sports-arena-recreational-summer-camp-franklin', ST_GeogFromText('SRID=4326;POINT(-71.3967 42.0834)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.unitedsportsarena.com/cricket-camps','https://www.unitedsportsarena.com/shop/summer-camp-2026-6549']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Twin Hills', 'Girl Scouts of the Green and White Mountains', 'https://www.girlscoutsgwm.org/en/activities/camp-and-outdoors/twin-hills.html', NULL, 'customercare@girlscoutsgwm.org', '888-474-9686', '2428 Wes White Hill', 'Richmond', 'VT', '05477', 'Vermont', 'day', ARRAY['outdoor']::text[], ARRAY['leadership','arts','STEM']::text[], ARRAY['campfire cooking','hiking','sing alongs','theme weeks','crafts','science experiments','leadership training']::text[], 'girls', NULL, NULL, 0, 10, 'A Girl Scout day camp on 184 wooded acres in Richmond, between Burlington and Montpelier, for girls entering kindergarten through 10th grade. Theme weeks mix crafts, science and fantasy with camp favorites like hiking, campfire cooking and sing alongs, and older girls can train as program aides or counselors in training.', 'outdoor', NULL, 200, 600, 375, 'session', NULL, TRUE, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, '[{"name": "Membership", "amount": 80, "per": "year", "required": true, "note": "Girl Scout membership for girls, October 1, 2026 to September 30, 2027. Campers who are not Girl Scouts buy it when registering."}, {"name": "Bus", "amount": 35, "per": "session", "required": false, "note": "To ride the bus each session; Twin Hills bus runs July 26 to 30 and August 2 to 6, 2027.", "source_url": "https://www.girlscoutsgwm.org/en/activities/camp-and-outdoors/camp-transportation.html"}]'::jsonb, '73fa36ea-b552-564e-be07-492ab812fb98', 'camp-twin-hills-richmond', ST_GeogFromText('SRID=4326;POINT(-72.9796 44.382)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.girlscoutsgwm.org/en/activities/camp-and-outdoors/camp-transportation.html','https://www.girlscoutsgwm.org/en/activities/camp-and-outdoors/twin-hills.html','https://www.girlscoutsgwm.org/en/get-involved/join.html']::text[], '2026-11-27', '2026-11-27', TRUE),
('Summer Days at the J', 'JCC Mid-Westchester', 'https://jccmw.org/summer-days/', 'https://operations.daxko.com/Online/4072/ProgramsV2/Search.mvc?category_ids=CAT700&', NULL, '(914) 725-7300', '999 Wilmot Rd', 'Scarsdale', 'NY', '10583', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['swimming','performing_arts','STEM','sports']::text[], ARRAY['swimming','gymnastics','dance','musical theater','STEAM','robotics','field trips','gardening','baking','music','sports','arts and crafts']::text[], NULL, 2, 12, NULL, 6, 'Day camp at JCC Mid-Westchester in Scarsdale for toddlers through grade 6. Explorers (twos to kindergarten) play, swim in the indoor pool, garden and bake; Adventurers (grades 1 to 6) pick a morning focus in aquatics, dance and performing arts, trips, gymnastics or STEAM and join general camp activities in the afternoon.', NULL, 'Jewish', 840, 7541, NULL, 'session', TRUE, NULL, FALSE, NULL, 'No refunds unless the JCC cancels the program, except for a documented medical reason or a move of more than 30 miles, prorated on written request with a $35 to $50 processing fee.', NULL, NULL, NULL, NULL, 2027, '[{"name": "Extended care (morning or afternoon)", "amount": 30, "per": "hour", "required": false, "note": "Early care 8:00 to 9:00 am for all; after care 4:00 to 6:00 pm for full day campers. Billed automatically, no pre registration."}]'::jsonb, '7c3f3bb2-23ce-589a-8895-5bf5c77bdfb6', 'summer-days-at-the-j-scarsdale', ST_GeogFromText('SRID=4326;POINT(-73.7846 40.9898)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://jccmw.org/summer-days/']::text[], '2026-11-26', '2026-11-26', TRUE)
